import {HK_COURSES} from './hk-routes.mjs';
const $=id=>document.getElementById(id);let observed=false,working=false,connected=false,refreshing=false;
$('referenceCourse').innerHTML=HK_COURSES.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');
const initial=new URLSearchParams(location.search).get('course');if(HK_COURSES.some(c=>c.id===initial))$('referenceCourse').value=initial;
const course=()=>HK_COURSES.find(c=>c.id===$('referenceCourse').value);
function points(){const meta=course();$('backToRacing').href='./?course='+meta.id;$('referencePoint').innerHTML=meta.coordinates.map((p,i)=>`<option value="${i}">${String(i+1).padStart(2,'0')} / ${i===0?meta.startName:i===meta.coordinates.length-1?meta.endName:'途經航點'}</option>`).join('');coordinates();}
function coordinates(){const p=course().coordinates[Number($('referencePoint').value)];$('pointCoordinate').textContent=`WGS84  ${p[1].toFixed(6)}, ${p[0].toFixed(6)}`;}
function controls(){for(const id of ['showPoint','previousPoint','nextPoint','zoomIn','zoomOut'])$(id).disabled=!connected||!observed||working;}
function showState(data){const state=data.state;connected=true;$('connectionStatus').textContent=data.evaluationActive?'原生程式正在執行評估，預覽操作已停用。':'UrbanGround 已連接 · 僅本機使用';if(data.evaluationActive)connected=false;$('tileStatus').textContent=`地圖載入 ${Number(state.tiles_progress).toFixed(1)}% · ${data.ready?'資料串流已穩定':'正在串流，請等候畫面更新'}`;$('observedPosition').textContent=`${state.lat.toFixed(5)}, ${state.lon.toFixed(5)} · ${state.mode}`;controls();}
async function image(){const response=await fetch('./api/urbanground/frame',{cache:'no-store'});if(!response.ok)throw Error('未能取得原生畫面');const url=URL.createObjectURL(await response.blob()),old=$('nativeFrame').dataset.url;$('nativeFrame').src=url;$('nativeFrame').dataset.url=url;$('nativeFrame').classList.add('loaded');$('framePlaceholder').hidden=true;if(old)URL.revokeObjectURL(old);observed=true;controls();}
async function refresh(){if(refreshing||working)return;refreshing=true;try{const response=await fetch('./api/urbanground/state',{cache:'no-store'}),data=await response.json();if(!data.ok)throw Error(data.error);showState(data);await image();}catch(error){connected=false;controls();$('connectionStatus').textContent=error.message||'本機 UrbanGround 尚未啟動';$('tileStatus').textContent='請執行 Start_UrbanGround.cmd，再按重新連接。';}finally{refreshing=false;}}
async function preview(){if(!connected||!observed||working)return;working=true;controls();$('connectionStatus').textContent='正在切換 KML 位置…';try{const response=await fetch('./api/urbanground/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({course:course().id,index:Number($('referencePoint').value)})}),data=await response.json();if(!data.ok)throw Error(data.error);showState(data);await image();}catch(error){$('connectionStatus').textContent=error.message;}finally{working=false;controls();}}
$('referenceCourse').onchange=points;$('referencePoint').onchange=coordinates;$('showPoint').onclick=preview;$('refreshReference').onclick=refresh;
for(const [id,offset] of [['previousPoint',-1],['nextPoint',1]])$(id).onclick=()=>{const index=Math.max(0,Math.min(course().coordinates.length-1,Number($('referencePoint').value)+offset));$('referencePoint').value=String(index);coordinates();preview();};
for(const [id,factor] of [['zoomIn',.5],['zoomOut',2]])$(id).onclick=async()=>{if(working||!observed)return;working=true;controls();try{const response=await fetch('./api/urbanground/zoom',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({factor})}),data=await response.json();if(!data.ok)throw Error(data.error);showState(data);await image();}catch(error){$('connectionStatus').textContent=error.message;}finally{working=false;controls();}};
points();refresh();setInterval(()=>{if(!document.hidden)refresh();},3000);
